<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/vendor.php';require_once __DIR__.'/../lib/validation.php';require_once __DIR__.'/../lib/crypto.php';require_once __DIR__.'/../lib/notifications.php';require_once __DIR__.'/../lib/idempotency.php';
send_cors_headers();$context=require_vendor(false);$vendor=$context['vendor'];$vendorId=$vendor['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';

function onboarding_sections(PDO $db,string $applicationId): array {$stmt=$db->prepare('SELECT section_code,data_json,is_complete,updated_at FROM vendor_onboarding_sections WHERE application_id=:id');$stmt->execute(['id'=>$applicationId]);$out=[];foreach($stmt->fetchAll() as $row){$out[$row['section_code']]=['data'=>json_decode((string)$row['data_json'],true)?:[],'complete'=>(bool)$row['is_complete'],'updated_at'=>$row['updated_at']];}return $out;}
function save_onboarding_section(PDO $db,string $applicationId,string $code,array $safeData,bool $complete=true): void {$stmt=$db->prepare('INSERT INTO vendor_onboarding_sections (application_id,section_code,data_json,is_complete,updated_at) VALUES (:application,:code,:data,:complete,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE data_json=VALUES(data_json),is_complete=VALUES(is_complete),updated_at=VALUES(updated_at)');$stmt->execute(['application'=>$applicationId,'code'=>$code,'data'=>json_encode($safeData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'complete'=>$complete?1:0]);}

$application=current_vendor_application($vendorId);
if($method==='GET'){
    $docs=$db->prepare('SELECT id,document_type,verification_status,rejection_reason,created_at FROM vendor_documents WHERE vendor_id=:vendor AND application_id=:application ORDER BY created_at');$docs->execute(['vendor'=>$vendorId,'application'=>$application['id']]);
    json_response(200,['success'=>true,'vendor'=>public_vendor($vendor),'application'=>['id'=>$application['id'],'reference'=>$application['reference'],'status'=>$application['status'],'completion_percent'=>(int)$application['completion_percent'],'decision_reason'=>$application['decision_reason']],'sections'=>onboarding_sections($db,$application['id']),'documents'=>$docs->fetchAll()]);
}
if(!in_array($application['status'],['draft','changes_requested'],true))json_response(409,['success'=>false,'message'=>'This application is locked while it is under review.']);

if($method==='PATCH'||$method==='PUT'){
    $section=trim((string)($_GET['section']??''));$body=get_json_body();$db->beginTransaction();
    try{
        if($section==='profile'){
            $common=validate_fields($body,['legal_name'=>'required|string|min:2|max:180','public_name'=>'required|string|min:2|max:180','primary_category'=>'required|string|max:100','story'=>'required|string|min:80|max:2000','preferred_language'=>'required|string|max:40','address'=>'required|string|min:8|max:180','city'=>'required|string|max:80','district'=>'string|max:80','state'=>'required|string|max:80','pincode'=>'required|pincode']);
            $db->prepare('INSERT INTO vendor_profiles (vendor_id,legal_name,public_name,primary_category,story,preferred_language,created_at,updated_at) VALUES (:vendor,:legal,:public,:category,:story,:language,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE legal_name=VALUES(legal_name),public_name=VALUES(public_name),primary_category=VALUES(primary_category),story=VALUES(story),preferred_language=VALUES(preferred_language),updated_at=UTC_TIMESTAMP()')->execute(['vendor'=>$vendorId,'legal'=>$common['legal_name'],'public'=>$common['public_name'],'category'=>$common['primary_category'],'story'=>$common['story'],'language'=>$common['preferred_language']]);
            $addressId=uuid_string();$db->prepare('DELETE FROM vendor_addresses WHERE vendor_id=:vendor AND address_type="registered"')->execute(['vendor'=>$vendorId]);$db->prepare('INSERT INTO vendor_addresses (id,vendor_id,address_type,address_line1,city,district,state,pincode,is_primary,created_at) VALUES (:id,:vendor,"registered",:address,:city,:district,:state,:pincode,1,UTC_TIMESTAMP())')->execute(['id'=>$addressId,'vendor'=>$vendorId,'address'=>$common['address'],'city'=>$common['city'],'district'=>$common['district'],'state'=>$common['state'],'pincode'=>$common['pincode']]);
            if($vendor['vendor_type']==='artisan'){$specific=validate_fields($body,['operating_model'=>'required|string|max:60','craft_tradition'=>'required|string|max:180','years_practising'=>'required|integer','maker_count'=>'required|integer']);$db->prepare('INSERT INTO vendor_artisan_profiles (vendor_id,operating_model,craft_tradition,years_practising,maker_count) VALUES (:vendor,:model,:craft,:years,:makers) ON DUPLICATE KEY UPDATE operating_model=VALUES(operating_model),craft_tradition=VALUES(craft_tradition),years_practising=VALUES(years_practising),maker_count=VALUES(maker_count)')->execute(['vendor'=>$vendorId,'model'=>$specific['operating_model'],'craft'=>$specific['craft_tradition'],'years'=>(int)$specific['years_practising'],'makers'=>(int)$specific['maker_count']]);}
            else{$specific=validate_fields($body,['legal_structure'=>'required|string|max:60','registration_number'=>'required|string|max:100','representative_name'=>'required|string|max:120','representative_designation'=>'required|string|max:100']);$db->prepare('INSERT INTO vendor_brand_profiles (vendor_id,legal_structure,registration_number,representative_name,representative_designation) VALUES (:vendor,:structure,:registration,:representative,:designation) ON DUPLICATE KEY UPDATE legal_structure=VALUES(legal_structure),registration_number=VALUES(registration_number),representative_name=VALUES(representative_name),representative_designation=VALUES(representative_designation)')->execute(['vendor'=>$vendorId,'structure'=>$specific['legal_structure'],'registration'=>$specific['registration_number'],'representative'=>$specific['representative_name'],'designation'=>$specific['representative_designation']]);}
            save_onboarding_section($db,$application['id'],'profile',array_merge($common,$specific));
        }elseif($section==='verification'){
            $data=validate_fields($body,['pan'=>'required|string','gst_status'=>'required|in:registered,exempt,applied','gstin'=>'string','udyam'=>'string|max:25','beneficiary'=>'required|string|max:150','bank_account'=>'required|string|min:8|max:18','bank_confirm'=>'required|string|min:8|max:18','ifsc'=>'required|ifsc']);
            $pan=strtoupper(preg_replace('/\s+/','',(string)$data['pan']));if(!preg_match('/^[A-Z]{5}[0-9]{4}[A-Z]$/',$pan))json_response(422,['success'=>false,'message'=>'Please correct the highlighted fields.','errors'=>['pan'=>'Enter a valid PAN.']]);if($data['bank_account']!==$data['bank_confirm']||!preg_match('/^[0-9]{8,18}$/',(string)$data['bank_account']))json_response(422,['success'=>false,'message'=>'Please correct the highlighted fields.','errors'=>['bank_confirm'=>'Bank account numbers must match.']]);
            $gstin=$data['gstin']?strtoupper((string)$data['gstin']):null;if($data['gst_status']==='registered'&&(!is_string($gstin)||!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/',$gstin)))json_response(422,['success'=>false,'message'=>'Please correct the highlighted fields.','errors'=>['gstin'=>'Enter a valid GSTIN.']]);
            $db->prepare('INSERT INTO vendor_tax_profiles (vendor_id,pan_encrypted,pan_last4,gst_status,gstin_encrypted,gstin_last4,udyam_encrypted,verification_status,updated_at) VALUES (:vendor,:pan,:pan4,:gst_status,:gstin,:gstin4,:udyam,"pending",UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE pan_encrypted=VALUES(pan_encrypted),pan_last4=VALUES(pan_last4),gst_status=VALUES(gst_status),gstin_encrypted=VALUES(gstin_encrypted),gstin_last4=VALUES(gstin_last4),udyam_encrypted=VALUES(udyam_encrypted),verification_status="pending",updated_at=UTC_TIMESTAMP()')->execute(['vendor'=>$vendorId,'pan'=>encrypt_sensitive($pan),'pan4'=>substr($pan,-4),'gst_status'=>$data['gst_status'],'gstin'=>$gstin?encrypt_sensitive($gstin):null,'gstin4'=>$gstin?substr($gstin,-4):null,'udyam'=>$data['udyam']?encrypt_sensitive((string)$data['udyam']):null]);
            $existing=$db->prepare('SELECT id FROM vendor_bank_accounts WHERE vendor_id=:vendor AND is_primary=1 LIMIT 1');$existing->execute(['vendor'=>$vendorId]);$bankId=$existing->fetchColumn()?:uuid_string();
            $db->prepare('INSERT INTO vendor_bank_accounts (id,vendor_id,beneficiary_name,account_number_encrypted,account_last4,ifsc_encrypted,verification_status,is_primary,created_at,updated_at) VALUES (:id,:vendor,:beneficiary,:account,:last4,:ifsc,"pending",1,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE beneficiary_name=VALUES(beneficiary_name),account_number_encrypted=VALUES(account_number_encrypted),account_last4=VALUES(account_last4),ifsc_encrypted=VALUES(ifsc_encrypted),verification_status="pending",updated_at=UTC_TIMESTAMP()')->execute(['id'=>$bankId,'vendor'=>$vendorId,'beneficiary'=>$data['beneficiary'],'account'=>encrypt_sensitive((string)$data['bank_account']),'last4'=>substr((string)$data['bank_account'],-4),'ifsc'=>encrypt_sensitive(strtoupper((string)$data['ifsc']))]);
            save_onboarding_section($db,$application['id'],'verification',['gst_status'=>$data['gst_status'],'pan_masked'=>'••••••'.substr($pan,-4),'gstin_masked'=>$gstin?'•••••••••••'.substr($gstin,-4):null,'bank_account_masked'=>mask_account_number((string)$data['bank_account']),'beneficiary'=>$data['beneficiary']]);
        }elseif($section==='store_delivery'){
            $data=validate_fields($body,['support_email'=>'required|email','support_phone'=>'required|mobile','store_description'=>'required|string|min:100|max:1500','dispatch_address'=>'required|string|min:10|max:300','dispatch_pin'=>'required|pincode','processing_min_days'=>'required|integer','processing_max_days'=>'required|integer','coverage_model'=>'required|in:all_india,states,pincodes','delivery_partners'=>'required|string|max:500','base_charge'=>'required|numeric','free_above'=>'numeric','cod'=>'boolean','fragile'=>'boolean']);
            if((int)$data['processing_min_days']<0||(int)$data['processing_max_days']<(int)$data['processing_min_days']||(float)$data['base_charge']<0)json_response(422,['success'=>false,'message'=>'Delivery time or charge range is invalid.']);
            $db->prepare('INSERT INTO vendor_store_profiles (vendor_id,store_name,description,support_email,support_mobile,created_at,updated_at) VALUES (:vendor,:name,:description,:email,:mobile,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE store_name=VALUES(store_name),description=VALUES(description),support_email=VALUES(support_email),support_mobile=VALUES(support_mobile),updated_at=UTC_TIMESTAMP()')->execute(['vendor'=>$vendorId,'name'=>$vendor['display_name'],'description'=>$data['store_description'],'email'=>strtolower((string)$data['support_email']),'mobile'=>preg_replace('/\D+/','',(string)$data['support_phone'])]);
            $db->prepare('INSERT INTO vendor_shipping_settings (vendor_id,coverage_model,processing_min_days,processing_max_days,courier_partners,base_charge,free_above,cod_enabled,fragile_handling,created_at,updated_at) VALUES (:vendor,:coverage,:min_days,:max_days,:couriers,:base,:free_above,:cod,:fragile,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE coverage_model=VALUES(coverage_model),processing_min_days=VALUES(processing_min_days),processing_max_days=VALUES(processing_max_days),courier_partners=VALUES(courier_partners),base_charge=VALUES(base_charge),free_above=VALUES(free_above),cod_enabled=VALUES(cod_enabled),fragile_handling=VALUES(fragile_handling),updated_at=UTC_TIMESTAMP()')->execute(['vendor'=>$vendorId,'coverage'=>$data['coverage_model'],'min_days'=>(int)$data['processing_min_days'],'max_days'=>(int)$data['processing_max_days'],'couriers'=>$data['delivery_partners'],'base'=>(float)$data['base_charge'],'free_above'=>$data['free_above']!==null?(float)$data['free_above']:null,'cod'=>filter_var($data['cod'],FILTER_VALIDATE_BOOL)?1:0,'fragile'=>filter_var($data['fragile'],FILTER_VALIDATE_BOOL)?1:0]);
            $db->prepare('DELETE FROM vendor_addresses WHERE vendor_id=:vendor AND address_type="dispatch"')->execute(['vendor'=>$vendorId]);$db->prepare('INSERT INTO vendor_addresses (id,vendor_id,address_type,address_line1,city,state,pincode,is_primary,created_at) VALUES (:id,:vendor,"dispatch",:address,"Pending city mapping","Pending state mapping",:pincode,1,UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'vendor'=>$vendorId,'address'=>$data['dispatch_address'],'pincode'=>$data['dispatch_pin']]);
            save_onboarding_section($db,$application['id'],'store_delivery',$data);
        }elseif($section==='policies_impact'){
            $data=validate_fields($body,['return_policy'=>'required|string|min:100|max:2000','cancellation_policy'=>'required|string|min:80|max:1500','damage_policy'=>'required|string|min:80|max:1500','handmade_policy'=>'required|string|min:80|max:1500','materials'=>'required|string|min:50|max:1200','packaging'=>'required|string|max:80','maker_payment'=>'required|string|max:80','authenticity'=>'required|boolean','claims_truth'=>'required|boolean','delivery_control'=>'required|boolean','customer_policy'=>'required|boolean']);
            foreach(['authenticity','claims_truth','delivery_control','customer_policy'] as $confirmation)if(!filter_var($data[$confirmation],FILTER_VALIDATE_BOOL))json_response(422,['success'=>false,'message'=>'All required declarations must be accepted.']);
            $db->prepare('INSERT INTO vendor_settings (vendor_id,return_policy,cancellation_policy,damage_policy,handmade_policy,materials_sourcing,packaging_approach,maker_payment_model,updated_at) VALUES (:vendor,:returns,:cancellation,:damage,:handmade,:materials,:packaging,:maker_payment,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE return_policy=VALUES(return_policy),cancellation_policy=VALUES(cancellation_policy),damage_policy=VALUES(damage_policy),handmade_policy=VALUES(handmade_policy),materials_sourcing=VALUES(materials_sourcing),packaging_approach=VALUES(packaging_approach),maker_payment_model=VALUES(maker_payment_model),updated_at=UTC_TIMESTAMP()')->execute(['vendor'=>$vendorId,'returns'=>$data['return_policy'],'cancellation'=>$data['cancellation_policy'],'damage'=>$data['damage_policy'],'handmade'=>$data['handmade_policy'],'materials'=>$data['materials'],'packaging'=>$data['packaging'],'maker_payment'=>$data['maker_payment']]);save_onboarding_section($db,$application['id'],'policies_impact',$data);
        }else json_response(404,['success'=>false,'message'=>'Unknown onboarding section.']);
        $sections=onboarding_sections($db,$application['id']);$completed=count(array_filter($sections,fn($s)=>$s['complete']));$percent=min(100,$completed*25);$db->prepare('UPDATE vendor_applications SET completion_percent=:percent,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['percent'=>$percent,'id'=>$application['id']]);$db->prepare('UPDATE vendors SET onboarding_status="in_progress",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$vendorId]);$db->commit();audit_event('vendor.onboarding_section_saved','vendor_application',$application['id'],['section'=>$section]);json_response(200,['success'=>true,'message'=>'Onboarding section saved.','section'=>$section,'completion_percent'=>$percent]);
    }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}

if($method==='POST'&&($_GET['action']??'')==='submit'){
    $sections=onboarding_sections($db,$application['id']);$required=['profile','verification','store_delivery','policies_impact'];$missing=array_values(array_filter($required,fn($code)=>empty($sections[$code]['complete'])));
    $requiredDocs=$vendor['vendor_type']==='artisan'?['artisan_identity','artisan_craft_proof','artisan_address_proof','pan_file','bank_proof','store_logo','store_banner','product_sample']:['brand_registration_proof','brand_identity','brand_authorization','pan_file','bank_proof','store_logo','store_banner','product_sample'];
    $stmt=$db->prepare('SELECT document_type,COUNT(*) AS total FROM vendor_documents WHERE application_id=:application GROUP BY document_type');$stmt->execute(['application'=>$application['id']]);$counts=array_column($stmt->fetchAll(),'total','document_type');$missingDocs=[];foreach($requiredDocs as $doc){$requiredCount=$doc==='product_sample'?3:1;if((int)($counts[$doc]??0)<$requiredCount)$missingDocs[]=$doc;}
    if($missing||$missingDocs)json_response(422,['success'=>false,'message'=>'Complete all onboarding sections and required documents before submission.','missing_sections'=>$missing,'missing_documents'=>$missingDocs]);$idem=begin_idempotent_request('vendor.onboarding.submit',$context['principal'],['application_id'=>$application['id']]);
    $db->beginTransaction();try{$db->prepare('UPDATE vendor_applications SET status="submitted",completion_percent=100,submitted_at=UTC_TIMESTAMP(),updated_at=UTC_TIMESTAMP() WHERE id=:id AND status IN ("draft","changes_requested")')->execute(['id'=>$application['id']]);$db->prepare('UPDATE vendors SET verification_status="submitted",onboarding_status="in_progress",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$vendorId]);record_status_change('vendor_application',$application['id'],$application['status'],'submitted');create_notification('vendor',$vendorId,'application_submitted','Application submitted','Your vendor application is queued for review.','../auth/status.php',['reference'=>$application['reference']]);audit_event('vendor.application_submitted','vendor_application',$application['id'],['reference'=>$application['reference']]);$response=['success'=>true,'message'=>'Application submitted for review.','application_reference'=>$application['reference'],'status'=>'submitted','redirect'=>'auth/status.php'];finish_idempotent_request($idem['id'],200,$response);$db->commit();json_response(200,$response);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
